import re

from sqlalchemy.orm import Session

from app.database.session import SessionLocal
from app.models.aptitude_question import AptitudeQuestion


# =========================================================
# DATA QUALITY VALIDATION
# =========================================================

def is_bad_question(question_data):
    """
    Detects malformed questions extracted from source documents.

    Returns:
        True  -> question should be rejected
        False -> question is acceptable
    """

    question = str(
        question_data.get("question", "")
    ).strip()

    option_a = str(
        question_data.get("option_a", "")
    ).strip()

    option_b = str(
        question_data.get("option_b", "")
    ).strip()

    option_c = str(
        question_data.get("option_c", "")
    ).strip()

    option_d = str(
        question_data.get("option_d", "")
    ).strip()

    explanation = str(
        question_data.get("explanation", "")
    ).strip()


    # -----------------------------------------------------
    # BASIC VALIDATION
    # -----------------------------------------------------

    if not question:
        return True

    if not option_a or not option_b or not option_c or not option_d:
        return True


    # -----------------------------------------------------
    # EXTREME LENGTH CHECK
    #
    # A normal aptitude question should not contain
    # several pages of source material.
    # -----------------------------------------------------

    if len(question) > 1200:
        return True

    if len(option_a) > 500:
        return True

    if len(option_b) > 500:
        return True

    if len(option_c) > 500:
        return True

    if len(option_d) > 500:
        return True


    # -----------------------------------------------------
    # SOURCE-DOCUMENT ARTIFACTS
    #
    # These appeared in the imported dataset.
    # -----------------------------------------------------

    bad_phrases = [

        "aptitude questions and answers",

        "aptitude questions with explanation",

        "aptitude questions",

        "questions and answers with explanation",

        "logical reasoning questions",

        "logical reasoning questions and answers",

        "quantitative aptitude questions",

        "verbal ability questions",

        "genpact aptitude",

        "accenture logical reasoning",

        "infosys aptitude",

        "tcs aptitude",

        "wipro aptitude",

        "cognizant aptitude",

        "capgemini aptitude",

        "sol:",

        "solution:",

    ]


    combined_text = (
        question
        + " "
        + option_a
        + " "
        + option_b
        + " "
        + option_c
        + " "
        + option_d
    ).lower()


    for phrase in bad_phrases:

        if phrase in combined_text:
            return True


    # -----------------------------------------------------
    # MULTIPLE QUESTION DETECTION
    #
    # Example of bad data:
    #
    # Question 1 ... A... B... C... D...
    # Question 2 ... A... B... C... D...
    #
    # -----------------------------------------------------

    question_mark_count = question.count("?")

    if question_mark_count > 2:
        return True


    # -----------------------------------------------------
    # DETECT MULTIPLE "SOL" BLOCKS
    # -----------------------------------------------------

    if len(
        re.findall(
            r"\bsol(?:ution)?\s*:",
            combined_text,
            flags=re.IGNORECASE
        )
    ) > 1:
        return True


    # -----------------------------------------------------
    # DETECT CONCATENATED OPTION STRUCTURE
    #
    # Example:
    #
    # "A. xxx B. xxx C. xxx D. xxx E. xxx"
    #
    # inside a single option.
    # -----------------------------------------------------

    for option in [
        option_a,
        option_b,
        option_c,
        option_d
    ]:

        option_pattern_count = len(
            re.findall(
                r"(?:^|\s)[A-E]\.",
                option
            )
        )

        if option_pattern_count >= 2:
            return True


    # -----------------------------------------------------
    # DETECT QUESTION-LIKE TEXT INSIDE OPTIONS
    # -----------------------------------------------------

    for option in [
        option_a,
        option_b,
        option_c,
        option_d
    ]:

        question_like_patterns = [

            r"\bwhat is\b",
            r"\bwhat are\b",
            r"\bwhich of the following\b",
            r"\bfind the\b",
            r"\bhow many\b",
            r"\bchoose the\b",
            r"\bif\s+.+\?",
        ]

        matches = 0

        for pattern in question_like_patterns:

            if re.search(
                pattern,
                option,
                flags=re.IGNORECASE
            ):
                matches += 1

        # An option can legitimately contain a phrase such as
        # "What is..." in rare cases, so only reject when
        # multiple question-like signals exist.
        if matches >= 2:
            return True


    # -----------------------------------------------------
    # DETECT EXCESSIVE SENTENCE COUNT
    #
    # Options should normally be short.
    # -----------------------------------------------------

    for option in [
        option_a,
        option_b,
        option_c,
        option_d
    ]:

        sentence_count = len(
            re.findall(
                r"[.!?]",
                option
            )
        )

        if sentence_count >= 3:
            return True


    # -----------------------------------------------------
    # VALID
    # -----------------------------------------------------

    return False


# =========================================================
# CLEAN EXISTING DATABASE RECORDS
# =========================================================

def clean_existing_questions(db: Session):

    print(
        "\nChecking existing aptitude questions..."
    )

    existing_questions = (
        db.query(AptitudeQuestion)
        .all()
    )

    deleted = 0

    for question in existing_questions:

        question_data = {

            "question":
                question.question,

            "option_a":
                question.option_a,

            "option_b":
                question.option_b,

            "option_c":
                question.option_c,

            "option_d":
                question.option_d,

            "explanation":
                question.explanation,

        }

        if is_bad_question(
            question_data
        ):

            db.delete(question)

            deleted += 1


    if deleted > 0:

        db.commit()

    print(
        f"Removed {deleted} malformed questions."
    )

    print(
        f"Remaining questions: "
        f"{db.query(AptitudeQuestion).count()}"
    )

    return deleted


# =========================================================
# SEED QUESTIONS
# =========================================================

def seed_questions():

    db: Session = SessionLocal()

    inserted = 0

    skipped = 0

    invalid = 0

    try:

        # -------------------------------------------------
        # FIRST CLEAN EXISTING DATABASE
        # -------------------------------------------------

        clean_existing_questions(
            db
        )


        # -------------------------------------------------
        # INSERT NEW QUESTIONS
        # -------------------------------------------------

        for question_data in QUESTIONS:

            # ---------------------------------------------
            # QUALITY CHECK
            # ---------------------------------------------

            if is_bad_question(
                question_data
            ):

                invalid += 1

                continue


            # ---------------------------------------------
            # DUPLICATE CHECK
            # ---------------------------------------------

            existing = (
                db.query(
                    AptitudeQuestion
                )
                .filter(
                    AptitudeQuestion.question
                    ==
                    question_data["question"]
                )
                .first()
            )


            if existing:

                skipped += 1

                continue


            # ---------------------------------------------
            # INSERT
            # ---------------------------------------------

            db.add(
                AptitudeQuestion(
                    **question_data
                )
            )

            inserted += 1


        # -------------------------------------------------
        # COMMIT
        # -------------------------------------------------

        db.commit()


        # -------------------------------------------------
        # FINAL COUNTS
        # -------------------------------------------------

        total_questions = (
            db.query(
                AptitudeQuestion
            )
            .count()
        )


        print(
            "\n=========================================="
        )

        print(
            "APTITUDE DATASET SEED COMPLETE"
        )

        print(
            "=========================================="
        )

        print(
            f"Inserted new questions : {inserted}"
        )

        print(
            f"Skipped duplicates     : {skipped}"
        )

        print(
            f"Rejected malformed     : {invalid}"
        )

        print(
            f"Final database size    : {total_questions}"
        )

        print(
            "=========================================="
        )


    except Exception:

        db.rollback()

        raise


    finally:

        db.close()


# =========================================================
# RUN
# =========================================================

if __name__ == "__main__":

    seed_questions()